import{_t as e,it as t,n,rt as r}from"./chunks/framework.gd_RGE3V.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireAssert Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireAssert/aireassert-v1-3-19.md","filePath":"aireblock-releases/AireAssert/aireassert-v1-3-19.md","lastUpdated":1794501798000}`),a={name:`aireblock-releases/AireAssert/aireassert-v1-3-19.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="aireassert-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireassert-icon.png"> AireAssert Release Notes</span> <a class="header-anchor" href="#aireassert-release-notes" aria-label="Permalink to “AireAssert Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.3.19<br><strong>Release Date:</strong> 18 November 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Run a Single Test from the Test List (AA-1074)</li><li>Re-run Only Failed Tests (AA-1075)</li><li>Progress Bar for Running Test Runs (AA-1067)</li><li>Supply Form Context to Single Pass Forms (AA-965)</li><li>reCAPTCHA Detection During Form Submission (AA-1045)</li><li>Keyboard Shortcut to Save Changes (AA-1049)</li><li>Log Out of All Open Tabs (AA-685)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Complete Video Recordings (AA-1073)</li><li>More Reliable Text Checks on Multi-Line Text (AA-921)</li></ul><h4 id="🔧-tasks" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks" aria-label="Permalink to “🔧 Tasks”">​</a></h4><ul><li>Automatic Focus on the Commit Message (AA-1058)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="run-a-single-test-from-the-test-list-aa-1074" tabindex="-1">Run a Single Test from the Test List (AA-1074) <a class="header-anchor" href="#run-a-single-test-from-the-test-list-aa-1074" aria-label="Permalink to “Run a Single Test from the Test List (AA-1074)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>A Run action is now available on individual tests in the test management list. The test runs in the UI, its result is shown in the results panel as normal and it is recorded in the test run history. You no longer need to open the Test Builder to run one test.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can check a single test straight from your test list, without running a whole test set or opening the builder. This makes it much quicker to confirm a fix or check one scenario.</p></div><h4 id="re-run-only-failed-tests-aa-1075" tabindex="-1">Re-run Only Failed Tests (AA-1075) <a class="header-anchor" href="#re-run-only-failed-tests-aa-1075" aria-label="Permalink to “Re-run Only Failed Tests (AA-1075)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>From a completed or interrupted test run, a Re-run failed action now starts a new run containing only the tests that failed or errored. The new run is recorded separately in the history and linked back to the original run. The action is hidden or disabled when every test passed, and it works for both full test set runs and ad-hoc runs.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When a few tests fail, you can re-run just those instead of the whole set. If a run is interrupted, for example by a deployment, you can pick up the affected tests without starting again from scratch.</p></div><h4 id="progress-bar-for-running-test-runs-aa-1067" tabindex="-1">Progress Bar for Running Test Runs (AA-1067) <a class="header-anchor" href="#progress-bar-for-running-test-runs-aa-1067" aria-label="Permalink to “Progress Bar for Running Test Runs (AA-1067)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The in-progress grid on the test run results page has a new Progress column after Status. For running test runs it shows a progress bar of completed scenarios, and hovering over it shows the exact count (for example 47/60). Each scenario generated by a scenario outline is counted separately, scenarios that are not run directly are excluded, and single-file runs count only that file&#39;s scenarios.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can see at a glance how far through a test run is and roughly how long is left, instead of waiting for it to finish.</p></div><h4 id="supply-form-context-to-single-pass-forms-aa-965" tabindex="-1">Supply Form Context to Single Pass Forms (AA-965) <a class="header-anchor" href="#supply-form-context-to-single-pass-forms-aa-965" aria-label="Permalink to “Supply Form Context to Single Pass Forms (AA-965)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>You can now supply key-value pairs as form context when testing single pass forms. The test runner encodes them and adds them to the form URL as the <code>context</code> parameter, so the form can read them in the same way it would in live use.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can test single pass forms that rely on pre-filled information, such as a person&#39;s email address passed in from another system, so your tests reflect how the form is really used.</p></div><h4 id="recaptcha-detection-during-form-submission-aa-1045" tabindex="-1">reCAPTCHA Detection During Form Submission (AA-1045) <a class="header-anchor" href="#recaptcha-detection-during-form-submission-aa-1045" aria-label="Permalink to “reCAPTCHA Detection During Form Submission (AA-1045)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When reCAPTCHA is turned on for a form and blocks submission during a test, AireAssert now records this in the test logs and shows it in the video recording.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If a test can&#39;t submit a form because of reCAPTCHA, you&#39;ll now see why straight away, rather than being left with a failed submission and no explanation.</p></div><h4 id="keyboard-shortcut-to-save-changes-aa-1049" tabindex="-1">Keyboard Shortcut to Save Changes (AA-1049) <a class="header-anchor" href="#keyboard-shortcut-to-save-changes-aa-1049" aria-label="Permalink to “Keyboard Shortcut to Save Changes (AA-1049)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Pressing Ctrl+S in the editor now saves your changes, working in exactly the same way as clicking the Save Changes button.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can save your work in the editor with a familiar keyboard shortcut instead of reaching for the mouse.</p></div><h4 id="log-out-of-all-open-tabs-aa-685" tabindex="-1">Log Out of All Open Tabs (AA-685) <a class="header-anchor" href="#log-out-of-all-open-tabs-aa-685" aria-label="Permalink to “Log Out of All Open Tabs (AA-685)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Logging out of AireAssert in one browser tab now logs you out of every other open AireAssert tab, which are redirected to the login screen.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>When you log out, you can be confident you&#39;re logged out everywhere, so no tab is left signed in on a shared or unattended computer.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="complete-video-recordings-aa-1073" tabindex="-1">Complete Video Recordings (AA-1073) <a class="header-anchor" href="#complete-video-recordings-aa-1073" aria-label="Permalink to “Complete Video Recordings (AA-1073)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where the last second or two of a test&#39;s video recording could be cut off, sometimes losing the final interaction.</p></div><h4 id="more-reliable-text-checks-on-multi-line-text-aa-921" tabindex="-1">More Reliable Text Checks on Multi-Line Text (AA-921) <a class="header-anchor" href="#more-reliable-text-checks-on-multi-line-text-aa-921" aria-label="Permalink to “More Reliable Text Checks on Multi-Line Text (AA-921)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Text checks on fields containing several lines or paragraphs, such as explanatory text, could fail because of differences in line breaks and spacing even when the wording matched. Line breaks and extra spaces are now ignored when comparing, while a change to the actual wording still fails the check.</p></div><h3 id="🔧-tasks-1" tabindex="-1">🔧 Tasks <a class="header-anchor" href="#🔧-tasks-1" aria-label="Permalink to “🔧 Tasks”">​</a></h3><hr><h4 id="automatic-focus-on-the-commit-message-aa-1058" tabindex="-1">Automatic Focus on the Commit Message (AA-1058) <a class="header-anchor" href="#automatic-focus-on-the-commit-message-aa-1058" aria-label="Permalink to “Automatic Focus on the Commit Message (AA-1058)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When you save changes, the cursor now goes straight to the commit message box, so you can start typing without clicking into it first.</p></div>`,42)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};